/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { AnalyzerScreen } from "../../src/analyzer-screen/AnalyzerScreen.js";
import { AnalyzerModel } from "../../src/analyzer-screen/model/AnalyzerModel.js";
import { AnalyzerViewProperties } from "../../src/analyzer-screen/view/AnalyzerViewProperties.js";
import { ComposerScreen } from "../../src/composer-screen/ComposerScreen.js";
import { ComposerModel } from "../../src/composer-screen/model/ComposerModel.js";
import { ComposerViewProperties } from "../../src/composer-screen/view/ComposerViewProperties.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { WaveComposerPreferencesModel } from "../../src/preferences/WaveComposerPreferencesModel.js";
import { VoiceModel } from "../../src/voice-screen/model/VoiceModel.js";
import { VoiceScreen } from "../../src/voice-screen/VoiceScreen.js";
import WaveComposerColors from "../../src/WaveComposerColors.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const screenNames = stringManager.getScreenNames();

  const analysisPreferences = new WaveComposerPreferencesModel(Tandem.ROOT.createTandem("preferences"));
  const analyzerModel = new AnalyzerModel(analysisPreferences);
  const composerModel = new ComposerModel(analysisPreferences);
  const voiceModel = new VoiceModel(analysisPreferences);

  const analyzerViewProperties = new AnalyzerViewProperties(analysisPreferences.colormapProperty);
  const composerViewProperties = new ComposerViewProperties();

  const screens = [
    new ComposerScreen(composerModel, {
      // The screen name Property updates automatically when the locale changes
      name: screenNames.composerStringProperty,
      tandem: Tandem.ROOT.createTandem("composerScreen"),
      backgroundColorProperty: WaveComposerColors.backgroundColorProperty,
      viewProperties: composerViewProperties,
    }),
    new AnalyzerScreen(analyzerModel, {
      // The screen name Property updates automatically when the locale changes
      name: screenNames.analyzerStringProperty,
      tandem: Tandem.ROOT.createTandem("analyzerScreen"),
      backgroundColorProperty: WaveComposerColors.backgroundColorProperty,
      viewProperties: analyzerViewProperties,
    }),
    new VoiceScreen(voiceModel, {
      // The screen name Property updates automatically when the locale changes
      name: screenNames.voiceStringProperty,
      tandem: Tandem.ROOT.createTandem("voiceScreen"),
      backgroundColorProperty: WaveComposerColors.backgroundColorProperty,
    }),
  ];

  return {
    screens,
    tracked: {
      WaveComposerColors,
      stringManager,
      analysisPreferences,
      analyzerModel,
      composerModel,
      voiceModel,
      analyzerViewProperties,
      composerViewProperties,
    },
  };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
